package io.github.mtsdurica.freezerplate.config;

import java.util.Optional;
import java.util.regex.Pattern;
import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * Configuration properties under the {@code freezerplate} prefix.
 */
@ConfigurationProperties(prefix = "freezerplate")
public final class FreezerplateProperties {

  private static final Pattern SURROUNDING_SLASHES = Pattern.compile("^/+|/+$");

  /**
   * Path prefix for all endpoints generated by Freezerplate, for example "/api". Not set by
   * default, so generated endpoints are served at the application's root.
   */
  private final String basePath;

  /**
   * Creates the properties; called by Spring Boot's configuration binding.
   *
   * @param basePath path prefix for all generated endpoints; leading and trailing slashes are
   *     optional, and {@code null} or blank means no prefix
   */
  public FreezerplateProperties(String basePath) {
    this.basePath =
        Optional.ofNullable(basePath)
            .map(path -> SURROUNDING_SLASHES.matcher(path.strip()).replaceAll(""))
            .filter(path -> !path.isEmpty())
            .map(path -> "/" + path)
            .orElse("");
  }

  /**
   * Returns the path prefix for all generated endpoints.
   *
   * @return the normalized prefix with a leading and no trailing slash, for example {@code /api},
   *     or empty when no prefix is configured
   */
  public Optional<String> getBasePath() {
    return basePath.isEmpty() ? Optional.empty() : Optional.of(basePath);
  }
}
